import { useState } from "react";
import {
  Avatar,
  Box,
  Card,
  CardContent,
  Container,
  Grid,
  IconButton,
  Stack,
  Typography,
} from "@mui/material";
import masterData from "../../data/masterData.json";
import {
  ChevronLeftIcon,
  ChevronRightIcon,
  FormatQuoteIcon,
} from "../../utils/iconMap";

export default function TestimonialsSection() {
  const { testimonials, sections } = masterData;
  const [start, setStart] = useState(0);
  const visibleCount = 3;

  const prev = () => {
    setStart((s) => (s - 1 + testimonials.length) % testimonials.length);
  };

  const next = () => {
    setStart((s) => (s + 1) % testimonials.length);
  };

  const visible = Array.from({ length: Math.min(visibleCount, testimonials.length) }, (_, i) => {
    return testimonials[(start + i) % testimonials.length];
  });

  return (
    <Box sx={{ py: { xs: 5, md: 8 }, bgcolor: "#FAFBFD" }}>
      <Container maxWidth="lg">
        <Stack
          direction="row"
          justifyContent="space-between"
          alignItems="center"
          sx={{ mb: 3 }}
        >
          <Typography
            variant="h4"
            sx={{ fontWeight: 800, color: "#0A2540", fontSize: { xs: "1.4rem", md: "2rem" } }}
          >
            {sections.testimonials.title}
          </Typography>
          <Stack direction="row" spacing={1}>
            <IconButton
              onClick={prev}
              sx={{ border: "1px solid #E8EEF5", bgcolor: "#fff" }}
              aria-label="Previous"
            >
              <ChevronLeftIcon />
            </IconButton>
            <IconButton
              onClick={next}
              sx={{ border: "1px solid #E8EEF5", bgcolor: "#fff" }}
              aria-label="Next"
            >
              <ChevronRightIcon />
            </IconButton>
          </Stack>
        </Stack>

        <Grid container spacing={2.5}>
          {visible.map((item) => (
            <Grid key={`${item.id}-${start}`} size={{ xs: 12, md: 4 }}>
              <Card sx={{ height: "100%", borderRadius: 2 }}>
                <CardContent sx={{ p: 3 }}>
                  <Stack spacing={2}>
                    <Avatar
                      src={item.avatar}
                      alt={item.name}
                      sx={{ width: 56, height: 56 }}
                    />
                    <Box sx={{ position: "relative", pl: 0.5 }}>
                      <FormatQuoteIcon
                        sx={{
                          color: "primary.light",
                          fontSize: 28,
                          opacity: 0.5,
                          mb: 0.5,
                        }}
                      />
                      <Typography
                        sx={{
                          color: "primary.main",
                          fontWeight: 500,
                          fontSize: 15,
                          lineHeight: 1.6,
                        }}
                      >
                        {item.quote}
                      </Typography>
                    </Box>
                    <Box>
                      <Typography sx={{ fontWeight: 700, color: "#0A2540", fontSize: 14 }}>
                        {item.name}
                      </Typography>
                      <Typography variant="caption" color="text.secondary">
                        {item.role}
                      </Typography>
                    </Box>
                  </Stack>
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>
      </Container>
    </Box>
  );
}
